-- 01_create_and_load.sql
-- Creates and loads the mock tables used in every comparison (T-SQL: SQL Server or Azure SQL).
-- The data is generated by formula and matches the Power Query mock queries in the
-- dax-pattern-cheat-sheet repo row for row, so SQL, Power Query, and DAX results can be compared.
-- All data is fabricated. Safe to re-run: existing tables are dropped first.

------------------------------------------------------------
-- FactInvoices: 120 invoices, Oct 2024 to Sep 2026
------------------------------------------------------------
DROP TABLE IF EXISTS dbo.FactInvoices;

CREATE TABLE dbo.FactInvoices (
    InvoiceID   INT           NOT NULL PRIMARY KEY,
    InvoiceDate DATE          NOT NULL,
    Program     VARCHAR(50)   NOT NULL,
    Vendor      VARCHAR(100)  NOT NULL,
    Amount      DECIMAL(12,2) NOT NULL
);

WITH Numbers AS (
    SELECT TOP (120) CAST(ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS INT) AS n
    FROM sys.all_objects AS a CROSS JOIN sys.all_objects AS b
)
INSERT INTO dbo.FactInvoices (InvoiceID, InvoiceDate, Program, Vendor, Amount)
SELECT
    n,
    DATEADD(DAY, (n * 37) % 730, CAST('2024-10-01' AS DATE)),
    CHOOSE((n % 3) + 1, 'Program A', 'Program B', 'Program C'),
    CHOOSE((n % 4) + 1, 'Acme Staffing', 'Globex Talent', 'Initech Services', 'Umbrella Workforce'),
    500 + (n * 173) % 4500
FROM Numbers;

------------------------------------------------------------
-- DimDate: daily calendar with an October fiscal year start
-- Fiscal year is named for the calendar year in which it ends (Oct 2025 to Sep 2026 = FY2026).
-- The + 12 before the modulo keeps the fiscal month positive for months before the fiscal start.
------------------------------------------------------------
DROP TABLE IF EXISTS dbo.DimDate;

CREATE TABLE dbo.DimDate (
    FullDate           DATE        NOT NULL PRIMARY KEY,
    MonthStart         DATE        NOT NULL,
    CalendarYear       INT         NOT NULL,
    MonthNumber        INT         NOT NULL,
    FiscalYear         INT         NOT NULL,
    FiscalMonth        INT         NOT NULL,
    FiscalQuarter      INT         NOT NULL,
    FiscalQuarterIndex INT         NOT NULL,
    FiscalPeriodLabel  VARCHAR(10) NOT NULL
);

DECLARE @FiscalStartMonth INT  = 10;
DECLARE @StartDate        DATE = '2024-10-01';
DECLARE @EndDate          DATE = '2026-12-31';

WITH Dates AS (
    SELECT TOP (DATEDIFF(DAY, @StartDate, @EndDate) + 1)
        DATEADD(DAY, CAST(ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS INT) - 1, @StartDate) AS DateValue
    FROM sys.all_objects AS a CROSS JOIN sys.all_objects AS b
)
INSERT INTO dbo.DimDate
    (FullDate, MonthStart, CalendarYear, MonthNumber, FiscalYear, FiscalMonth, FiscalQuarter, FiscalQuarterIndex, FiscalPeriodLabel)
SELECT
    dt.DateValue,
    DATEFROMPARTS(YEAR(dt.DateValue), MONTH(dt.DateValue), 1),
    YEAR(dt.DateValue),
    MONTH(dt.DateValue),
    fy.FiscalYear,
    fm.FiscalMonth,
    ((fm.FiscalMonth - 1) / 3) + 1,
    fy.FiscalYear * 4 + ((fm.FiscalMonth - 1) / 3) + 1,
    CONCAT('FY', fy.FiscalYear, ' Q', ((fm.FiscalMonth - 1) / 3) + 1)
FROM Dates AS dt
CROSS APPLY (
    SELECT CASE
               WHEN @FiscalStartMonth > 1 AND MONTH(dt.DateValue) >= @FiscalStartMonth
                   THEN YEAR(dt.DateValue) + 1
               ELSE YEAR(dt.DateValue)
           END AS FiscalYear
) AS fy
CROSS APPLY (
    SELECT ((MONTH(dt.DateValue) - @FiscalStartMonth + 12) % 12) + 1 AS FiscalMonth
) AS fm;

------------------------------------------------------------
-- FactSLA: 3 programs x 3 metrics x 24 months = 216 rows
-- Each row carries its own goal and a flag for whether higher or lower is better.
------------------------------------------------------------
DROP TABLE IF EXISTS dbo.FactSLA;

CREATE TABLE dbo.FactSLA (
    Program        VARCHAR(50)   NOT NULL,
    MonthStart     DATE          NOT NULL,
    Metric         VARCHAR(100)  NOT NULL,
    Goal           DECIMAL(10,2) NOT NULL,
    HigherIsBetter BIT           NOT NULL,
    Result         DECIMAL(10,2) NOT NULL
);

WITH Numbers AS (
    SELECT TOP (216) CAST(ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS INT) - 1 AS n
    FROM sys.all_objects AS a CROSS JOIN sys.all_objects AS b
)
INSERT INTO dbo.FactSLA (Program, MonthStart, Metric, Goal, HigherIsBetter, Result)
SELECT
    CHOOSE((n % 3) + 1, 'Program A', 'Program B', 'Program C'),
    DATEADD(MONTH, n / 9, CAST('2024-10-01' AS DATE)),
    CHOOSE(((n / 3) % 3) + 1, 'On-Time Fill %', 'Invoice Accuracy %', 'Time to Fill (days)'),
    CHOOSE(((n / 3) % 3) + 1, 0.90, 0.98, 30),
    CASE WHEN ((n / 3) % 3) = 2 THEN 0 ELSE 1 END,
    CASE WHEN ((n / 3) % 3) = 2
         THEN 24 + (n * 5) % 14
         ELSE ROUND(0.85 + ((n * 7) % 15) / 100.0, 2)
    END
FROM Numbers;

------------------------------------------------------------
-- Quick checks: expect 120, 822, and 216 rows
------------------------------------------------------------
SELECT 'FactInvoices' AS TableName, COUNT(*) AS Rows FROM dbo.FactInvoices
UNION ALL SELECT 'DimDate', COUNT(*) FROM dbo.DimDate
UNION ALL SELECT 'FactSLA', COUNT(*) FROM dbo.FactSLA;
